global.configModule = configModule;
global.configLoaderModule = configLoaderModule;

function main() {
    var testFiles = process.argv.slice(2);
    console.log('═══════════════════════════════════════════');
    console.log('  DMTools Agent Unit Tests (Node harness)');
    console.log('═══════════════════════════════════════════');

    for (var i = 0; i < testFiles.length; i++) {
