'use strict';
/**
 * Pack launch-surface contract (Wave 2, owner decision 2026-10-01).
 *
 * Teammate packs must be SELF-SUFFICIENT in their release zips: the launch
 * config (`launch.json` — "how to launch me") and the loop verdict logic
 * (`loop/verdict.sh`) travel INSIDE the zip and version with the pack, so a
 * factory that has the unpacked pack needs no parallel dmtools-agents tree
 * checkout for them. `install.sh` / `cache.sh` deliberately STAY in the
 * tree (owner decision): they install toolchain dependencies, they do not
 * describe the agent.
 *
 * Surface per pack (added by ci/release_packs.mjs after `dmtools compile`):
 *   launch.json      verbatim copy of the root entry config <agent>.json
 *   loop/verdict.sh  verbatim copy of setup/review-verdict.sh (review packs)
 *
 * Config-path audit (Wave 2 step 2): every tree reference in the four
 * launch configs (`metadata.descriptionPath` = agents/docs/agents/<a>.md,
 * `cliCommands` = ./agents/scripts/run-agent.sh, JS actions, cliPrompts)
 * already lands INSIDE the zip — the compiler embeds the referenced files
 * (agents/ prefix stripped) and the runtime resolver rewrites the config
 * paths to the pack root. No config edits needed; this module only ADDS
 * the two contract files.
 */

/** Repo-relative source of the review-loop verdict logic. */
var VERDICT_SOURCE = 'setup/review-verdict.sh';

/**
 * The teammate packs that carry a launch surface, and which files they add.
 * `verdict: true` → loop/verdict.sh rides along (review-loop packs only;
 * the dev packs currently have no in-pack loop logic).
 */
var TEAMMATE_LAUNCH_PACKS = {
  pr_review: { launch: true, verdict: true },
  pr_rework: { launch: true, verdict: true },
  story_development: { launch: true },
  bug_development: { launch: true },
};

/** True when [agent] is a teammate pack carrying a launch surface. */
function isTeammatePack(agent) {
  return Object.prototype.hasOwnProperty.call(TEAMMATE_LAUNCH_PACKS, agent);
}

/**
 * Zip additions for [agent]: `[{ entry, source }]` (entry = path inside the
 * zip, source = repo-relative file to copy verbatim). Non-teammate packs
 * get an empty list (their zips stay exactly as `dmtools compile` built
 * them).
 */
function launchExtras(agent) {
  if (!isTeammatePack(agent)) return [];
  var extras = [{ entry: 'launch.json', source: agent + '.json' }];
  if (TEAMMATE_LAUNCH_PACKS[agent].verdict) {
    extras.push({ entry: 'loop/verdict.sh', source: VERDICT_SOURCE });
  }
  return extras;
}

/**
 * Pure manifest merge: folds `added` (`[{path, sha256, mode}]`) into a
 * compile manifest, replacing same-path entries and keeping `files` sorted
 * by path (the manifest inventory order the compiler emits). The rest of
 * the manifest (agent/version/sourceCommit/defaultEntry/...) passes through
 * untouched — the catalog.json format is NOT affected by this contract.
 */
function mergeManifest(manifest, added) {
  var byPath = {};
  var files = manifest.files || [];
  for (var i = 0; i < files.length; i++) {
    byPath[files[i].path] = files[i];
  }
  for (var j = 0; j < added.length; j++) {
    var a = added[j];
    byPath[a.path] = { path: a.path, sha256: a.sha256, mode: a.mode };
  }
  var merged = Object.keys(byPath).map(function (p) { return byPath[p]; });
  merged.sort(function (x, y) { return x.path < y.path ? -1 : x.path > y.path ? 1 : 0; });
  var out = {};
  Object.keys(manifest).forEach(function (k) { out[k] = manifest[k]; });
  out.files = merged;
  return out;
}

module.exports = {
  VERDICT_SOURCE: VERDICT_SOURCE,
  TEAMMATE_LAUNCH_PACKS: TEAMMATE_LAUNCH_PACKS,
  isTeammatePack: isTeammatePack,
  launchExtras: launchExtras,
  mergeManifest: mergeManifest,
};

/**
 * Node-based test harness for agent unit tests.
 *
 * Mirrors the GraalJS testRunner API so the same test files can be executed
 * in environments where the dmtools JSRunner is not available.
 */

const fs = require('fs');
const path = require('path');

var _results_ = { passed: 0, failed: 0, errors: [] };
var _currentSuite_ = 'default';

function test(name, fn) {
    var fullName = _currentSuite_ + ' > ' + name;
    try {
        fn();
        _results_.passed++;
        console.log('  ✅ ' + fullName);
    } catch (e) {
        _results_.failed++;
        var msg = e.message || String(e);
        _results_.errors.push({ name: fullName, error: msg });
        console.log('  ❌ ' + fullName);
        console.log('     ' + msg);
    }
}

function suite(name, fn) {
    var prev = _currentSuite_;
    _currentSuite_ = name;
    console.log('\n── ' + name + ' ──');
    fn();
    _currentSuite_ = prev;
}

var assert = {
    equal: function(actual, expected, msg) {
        if (actual !== expected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected ' + JSON.stringify(expected) + ' but got ' + JSON.stringify(actual)
            );
        }
    },
    notEqual: function(actual, unexpected, msg) {
        if (actual === unexpected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected value to not equal ' + JSON.stringify(unexpected)
            );
        }
    },
    deepEqual: function(actual, expected, msg) {
        var a = JSON.stringify(actual);
        var b = JSON.stringify(expected);
        if (a !== b) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                '\n  expected: ' + b +
                '\n  actual:   ' + a
            );
        }
    },
    ok: function(val, msg) {
        if (!val) {
            throw new Error(msg || ('expected truthy, got: ' + JSON.stringify(val)));
        }
    },
    notOk: function(val, msg) {
        if (val) {
            throw new Error(msg || ('expected falsy, got: ' + JSON.stringify(val)));
        }
    },
    contains: function(str, substr, msg) {
        if (typeof str !== 'string' || str.indexOf(substr) === -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' does not contain ' + JSON.stringify(substr)
            );
        }
    },
    notContains: function(str, substr, msg) {
        if (typeof str === 'string' && str.indexOf(substr) !== -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' should not contain ' + JSON.stringify(substr)
            );
        }
    },
    throws: function(fn, msg) {
        var threw = false;
        try { fn(); } catch (e) { threw = true; }
        if (!threw) {
            throw new Error(msg || 'expected function to throw but it did not');
        }
    }
};

function file_read(args) {
    var p = args && args.path ? args.path : args;
    var resolved = path.resolve(process.cwd(), p);
    if (!fs.existsSync(resolved) && p.indexOf('js/') === 0) {
        resolved = path.resolve(process.cwd(), 'agents', p);
    }
    if (!fs.existsSync(resolved) && p.indexOf('agents/') !== 0) {
        resolved = path.resolve(process.cwd(), 'agents', p);
    }
    if (!fs.existsSync(resolved)) {
        throw new Error('file_read: file not found: ' + p);
    }
    return fs.readFileSync(resolved, 'utf8');
}

function loadModule(modulePath, requireFn, mocks) {
    var code = file_read(modulePath);
    if (!code || !code.trim()) {
        throw new Error('loadModule: cannot read file: ' + modulePath);
    }

    var _testMocks_ = mocks || {};
    var preamble = '';
    for (var k in _testMocks_) {
        if (Object.prototype.hasOwnProperty.call(_testMocks_, k)) {
            preamble += 'var ' + k + ' = _testMocks_["' + k + '"];\n';
        }
    }

    var _testModule_ = { exports: {} };
    var _testRequire_ = requireFn || function(id) {
        throw new Error('loadModule: require("' + id + '") not provided for ' + modulePath);
    };

    eval(
        '(function(module, exports, require) {\n' +
        preamble +
        code +
        '\n})(_testModule_, _testModule_.exports, _testRequire_)'
    );

    return _testModule_.exports;
}

function makeRequire(moduleMap) {
    return function(id) {
        if (moduleMap[id]) return moduleMap[id];

        var base = id;
        var slash = id.lastIndexOf('/');
        if (slash !== -1) base = id.substring(slash + 1);
        var noExt = base.replace(/\.js$/, '');

        if (moduleMap[base]) return moduleMap[base];
        if (moduleMap[noExt]) return moduleMap[noExt];
        if (moduleMap['./' + base]) return moduleMap['./' + base];

        throw new Error('makeRequire: module not found: ' + id);
    };
}

// Expose globals used by test files and modules
global.test = test;
global.suite = suite;
global.assert = assert;
global.loadModule = loadModule;
global.makeRequire = makeRequire;
global.file_read = file_read;

global.java = { lang: { System: { getenv: function() { return null; } } } };

// Pre-load base modules exactly like GraalJS testRunner does.
var configModule = loadModule('agents/js/config.js');
var scmModule = loadModule('agents/js/common/scm.js', require);
var configLoaderModule = loadModule(
    'agents/js/configLoader.js',
    makeRequire({
        './config.js': configModule,
        'config': configModule,
        './common/scm.js': scmModule,
        'scm': scmModule
    })
);

global.configModule = configModule;
global.configLoaderModule = configLoaderModule;

function main() {
    var testFiles = process.argv.slice(2);
    console.log('═══════════════════════════════════════════');
    console.log('  DMTools Agent Unit Tests (Node harness)');
    console.log('═══════════════════════════════════════════');

    for (var i = 0; i < testFiles.length; i++) {
        var filePath = testFiles[i];
        console.log('\n📂 ' + filePath);
